mapper.select:
SELECT COUNT(*)
FROM job
WHERE job_id = #{jobId}

SELECT COUNT(*)
FROM hr_position
WHERE position_id = #{positionId}

SELECT COUNT(*)
FROM hr_rank
WHERE rank_id = #{rankId}

SELECT COUNT(*)
FROM working_area
WHERE area_id = #{areaId}

SELECT COUNT(*)
FROM role
WHERE role_id = #{roleId}

